using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog; using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeCatalogQueryTests{[Fact]public void Default_query_has_default_page_order_and_fingerprint(){var q=new AstronomyKnowledgeCatalogQuery();Assert.Equal(AstronomyKnowledgeQueryPage.Default,q.Page);Assert.Equal(new[]{AstronomyKnowledgeCatalogSortField.Kind,AstronomyKnowledgeCatalogSortField.Order,AstronomyKnowledgeCatalogSortField.Code,AstronomyKnowledgeCatalogSortField.Id},q.Ordering.Select(o=>o.Field));Assert.Equal(64,q.Fingerprint.Value.Length);}[Fact]public void Filters_are_copied_and_normalized(){var ids=new List<AstronomyKnowledgeCatalogEntryId>{new(AstronomyKnowledgeCatalogEntryKind.KnowledgeType,"z"),new(AstronomyKnowledgeCatalogEntryKind.Domain,"a")};var q=new AstronomyKnowledgeCatalogQuery(entryIds:ids,entryKinds:[AstronomyKnowledgeCatalogEntryKind.KnowledgeType,AstronomyKnowledgeCatalogEntryKind.Domain],codes:["z","a","a"],domains:new([AstronomyKnowledgeDomain.Physical]),families:new([AstronomyKnowledgePayloadFamily.PhysicalProperty]),knowledgeTypes:new([AstronomyKnowledgeTypeId.Create("z")]),page:new(1,2));ids.Add(new(AstronomyKnowledgeCatalogEntryKind.Domain,"b"));Assert.Equal("Domain:a",q.EntryIds![0].ToString());Assert.Equal(new[]{"a","z"},q.Codes);Assert.Equal(1,q.Page.Offset);Assert.Throws<NotSupportedException>(()=>((IList<string>)q.Codes!).Add("x"));}[Fact]public void Input_order_normalizes_same_fingerprint(){var a=new AstronomyKnowledgeCatalogQuery(codes:["b","a"]);var b=new AstronomyKnowledgeCatalogQuery(codes:["a","b"]);Assert.Equal(a.Fingerprint,b.Fingerprint);}[Fact]public void Empty_filters_rejected_and_no_execution_api_exists(){Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeCatalogQuery(codes:[]));Assert.DoesNotContain(typeof(AstronomyKnowledgeCatalogQuery).GetMethods(),m=>m.Name.Contains("Query")||m.Name.Contains("Execute")||m.Name.Contains("Search"));}}
